/** 一条文案的三语版本；缺某个语言时回退 zh-CN。 */
type Entry = Record<Lang, string>;

const D = (zh: string, en: string, ja: string): Entry => ({ "zh-CN": zh, "en-US": en, "ja-JP": ja });

