/** 当前界面语言：settings 可能随时改，所以每次现读内存值（getSettings 已是内存快照，不读盘）。 */
function currentLang(): Lang {
  const lang = getSettings().language;
  return lang === "en-US" || lang === "ja-JP" ? lang : "zh-CN";
}

/**
 * 主进程文案：供 throw 的 message 与任务标题/阶段使用。
 * 缺语言回退 zh-CN；缺 key 直接返回 key 本身，便于一眼看出漏翻。
 */
export function mt(key: string, vars?: Record<string, string | number>): string {
  const entry = DICT[key];
  const raw = entry ? entry[currentLang()] ?? entry["zh-CN"] : key;
  if (!vars) return raw;
  return raw.replace(/\{(\w+)\}/g, (match, name: string) => (name in vars ? String(vars[name]) : match));
}
